SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name FROM song_masters sm JOIN albums a ON a.id=sm.album_id WHERE sm.album_id!='pending-uploads' AND lower(trim(sm.title)) IN ('头脑混乱中','奇遇与你','她是我修炼不好的爱情','如意年','如果天边太遥远','如果天边太遥远-inst','如见青山','妄语人间','始见千秋','孤独患者','孤独的吸血者','实力之上','对号入座','对症下药','射手座','将军行','小房间','尘华','尘埃河外系(feat.玖辰,星渺）','就让你孤独的长大','山河令','山鬼','巨蟹座','平静火','幽灵','废弃物的空中舞会(feat.铃霜,铃诺,铃幽)','开始 - initiate','归钓吟','往生','微光之影(feat.试作音demo)','微苦型日记','徵羽摩柯 , 人为的独立 - artificial independence','徵羽摩柯 , 共生之愿 - symbiotic wish','徵羽摩柯 , 告别大地 - say goodbye to the earth','徵羽摩柯 , 弗兰肯斯坦 - frankenstein') ORDER BY sm.title,sm.album_id